import{_ as e,o as l,c as t,a3 as r}from"./chunks/framework.Dj4Lt7vj.js";const u=JSON.parse('{"title":"错误报告","description":"","frontmatter":{"title":"错误报告"},"headers":[],"relativePath":"client/report.md","filePath":"client/report.md","lastUpdated":1787948622000}'),i={name:"client/report.md"};function o(n,a,s,d,p,c){return l(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="错误报告" tabindex="-1">错误报告 <a class="header-anchor" href="#错误报告" aria-label="Permalink to &quot;错误报告&quot;">​</a></h1><p>软件出问题时，一份完整的错误报告能让支持人员更快定位原因。这一页讲怎么生成报告、以及错误上报设置的含义。</p><h2 id="生成错误报告" tabindex="-1">生成错误报告 <a class="header-anchor" href="#生成错误报告" aria-label="Permalink to &quot;生成错误报告&quot;">​</a></h2><ol><li>打开客户端左侧菜单里的「错误报告」入口（在辅助菜单中）。</li><li>客户端会自动打包日志，生成一个错误报告 ZIP 文件。</li><li>生成后文件管理器会自动打开并选中该文件。</li><li>把这个 ZIP 直接发送到微信服务群，支持人员会跟进处理。</li></ol><p>报告也会同时上报到服务端并生成报告 ID，方便支持人员检索。</p><h2 id="错误上报设置" tabindex="-1">错误上报设置 <a class="header-anchor" href="#错误上报设置" aria-label="Permalink to &quot;错误上报设置&quot;">​</a></h2><p>入口：「设置」→「错误上报」。</p><p><strong>本地保存详细错误材料</strong>开关控制报错时保存的内容范围：</p><ul><li>开启后，平台脚本报错时会把当前页面截图和 HTML 快照保存到本地错误报告目录。</li><li>自动上报只发送报告 ID 和必要摘要，<strong>不包含</strong>截图与快照。</li><li>截图与快照仅在你主动「上报错误」时随日志包一起上传，用于排查问题。</li></ul><p>如果你对页面内容敏感，可以关闭这个开关，代价是排查平台页面相关的问题会慢一些。</p><h2 id="什么时候需要报错" tabindex="-1">什么时候需要报错 <a class="header-anchor" href="#什么时候需要报错" aria-label="Permalink to &quot;什么时候需要报错&quot;">​</a></h2><ul><li>AI 停止回复、消息读取异常。</li><li>平台窗口反复掉线或行为异常。</li><li>客户端崩溃、卡死。</li></ul><p>报错前建议先做两件事：升级客户端到最新版本、重启客户端。很多平台页面改版引起的问题在新版本里已经修复。</p><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/aicare-docs/faq/report">遇到故障怎么反馈</a></li></ul>',15)])])}const _=e(i,[["render",o]]);export{u as __pageData,_ as default};
